Convex 1.44.0. A workspace has 205 small activityLog rows. Each 100-row batch fits all transaction limits. There are no other writes. The client calls `deleteActivityLogs`; later, the scheduled mutation runs and fails with the shown error.

```ts
import { mutation, internalMutation } from "./_generated/server";
import type { MutationCtx } from "./_generated/server";
import { internal } from "./_generated/api";
import { v } from "convex/values";

async function deleteBatch(ctx: MutationCtx, workspaceId: string) {
  const batch = await ctx.db.query("activityLog")
    .withIndex("by_workspaceId", q => q.eq("workspaceId", workspaceId))
    .take(100);
  for (const entry of batch) await ctx.db.delete("activityLog", entry._id);
  return batch.length;
}

export const deleteActivityLogs = mutation({
  args: { workspaceId: v.string() },
  handler: async (ctx, args) => {
    const count = await deleteBatch(ctx, args.workspaceId);
    if (count === 100) {
      await ctx.scheduler.runAfter(0, internal.index.continueDelete, args);
    }
    return null;
  },
});

export const continueDelete = internalMutation({
  args: { workspaceId: v.string() },
  handler: async (ctx, args) => {
    await deleteBatch(ctx, args.workspaceId);
    throw new Error("Continuation failed");
  },
});
```
